package alphametics

import (
	"errors"
	"sort"
	"strings"
)

var (
	errInvalid  = errors.New("invalid puzzle")
	errNoSolution = errors.New("no solution")
)

type term struct {
	letter int
	count  int
}

type column struct {
	terms  []term
	result int
}

type solver struct {
	columns []column
	nonzero []bool
	digitOf []int
	used    [10]bool
}

func Solve(puzzle string) (map[string]int, error) {
	addends, result, err := parsePuzzle(puzzle)
	if err != nil {
		return nil, err
	}

	letters := make(map[byte]int)
	order := make([]byte, 0, 10)
	for _, word := range addends {
		for i := 0; i < len(word); i++ {
			indexLetter(letters, &order, word[i])
		}
	}
	for i := 0; i < len(result); i++ {
		indexLetter(letters, &order, result[i])
	}
	if len(order) > 10 {
		return nil, errInvalid
	}

	nonzero := make([]bool, len(order))
	words := append(append([]string{}, addends...), result)
	for _, word := range words {
		if len(word) > 1 {
			nonzero[indexLetter(letters, &order, word[0])] = true
		}
	}

	maxAddendLen := 0
	for _, word := range addends {
		if len(word) > maxAddendLen {
			maxAddendLen = len(word)
		}
	}
	if maxAddendLen > len(result) {
		return nil, errNoSolution
	}

	columns := make([]column, len(result))
	for c := 0; c < len(result); c++ {
		counts := make([]int, len(order))
		for _, word := range addends {
			p := len(word) - 1 - c
			if p >= 0 {
				counts[indexLetter(letters, &order, word[p])]++
			}
		}
		terms := make([]term, 0, len(order))
		for letter, count := range counts {
			if count > 0 {
				terms = append(terms, term{letter: letter, count: count})
			}
		}
		sort.Slice(terms, func(i, j int) bool {
			if terms[i].count != terms[j].count {
				return terms[i].count > terms[j].count
			}
			return terms[i].letter < terms[j].letter
		})
		columns[c] = column{terms: terms, result: indexLetter(letters, &order, result[len(result)-1-c])}
	}

	digitOf := make([]int, len(order))
	for i := range digitOf {
		digitOf[i] = -1
	}
	s := &solver{columns: columns, nonzero: nonzero, digitOf: digitOf}
	if !s.solveColumn(0, 0) {
		return nil, errNoSolution
	}

	out := make(map[string]int, len(order))
	for ch, idx := range letters {
		out[string(ch)] = s.digitOf[idx]
	}
	return out, nil
}

func parsePuzzle(puzzle string) ([]string, string, error) {
	parts := strings.Split(puzzle, "==")
	if len(parts) != 2 {
		return nil, "", errInvalid
	}
	result := strings.TrimSpace(parts[1])
	if !validWord(result) {
		return nil, "", errInvalid
	}
	rawAddends := strings.Split(strings.TrimSpace(parts[0]), "+")
	addends := make([]string, 0, len(rawAddends))
	for _, raw := range rawAddends {
		word := strings.TrimSpace(raw)
		if !validWord(word) {
			return nil, "", errInvalid
		}
		addends = append(addends, word)
	}
	return addends, result, nil
}

func validWord(word string) bool {
	if word == "" {
		return false
	}
	for i := 0; i < len(word); i++ {
		if word[i] < 'A' || word[i] > 'Z' {
			return false
		}
	}
	return true
}

func indexLetter(letters map[byte]int, order *[]byte, ch byte) int {
	if idx, ok := letters[ch]; ok {
		return idx
	}
	idx := len(*order)
	letters[ch] = idx
	*order = append(*order, ch)
	return idx
}

func (s *solver) solveColumn(col, carry int) bool {
	if col == len(s.columns) {
		if carry != 0 {
			return false
		}
		for _, d := range s.digitOf {
			if d < 0 {
				return false
			}
		}
		return true
	}
	c := s.columns[col]
	return s.assignTerms(col, c, 0, 0, carry)
}

func (s *solver) assignTerms(col int, c column, pos, partial, carry int) bool {
	if pos == len(c.terms) {
		return s.finishColumn(col, c, partial+carry)
	}
	if !s.rangePossible(c, pos, partial, carry) {
		return false
	}
	t := c.terms[pos]
	start := 0
	if s.nonzero[t.letter] {
		start = 1
	}
	for d := start; d < 10; d++ {
		if s.used[d] {
			continue
		}
		s.used[d] = true
		s.digitOf[t.letter] = d
		if s.assignTerms(col, c, pos+1, partial+t.count*d, carry) {
			return true
		}
		s.digitOf[t.letter] = -1
		s.used[d] = false
	}
	return false
}

func (s *solver) rangePossible(c column, pos, partial, carry int) bool {
	min, max, ok := s.remainingBounds(c.terms, pos)
	if !ok {
		return false
	}
	lo, hi := partial+carry+min, partial+carry+max
	if d := s.digitOf[c.result]; d >= 0 {
		return hasCongruent(lo, hi, d)
	}
	for d := 0; d < 10; d++ {
		if s.used[d] || (s.nonzero[c.result] && d == 0) {
			continue
		}
		if hasCongruent(lo, hi, d) {
			return true
		}
	}
	return false
}

func (s *solver) remainingBounds(terms []term, pos int) (int, int, bool) {
	min, max := 0, 0
	for ; pos < len(terms); pos++ {
		t := terms[pos]
		low := -1
		start := 0
		if s.nonzero[t.letter] {
			start = 1
		}
		for d := start; d < 10; d++ {
			if !s.used[d] {
				low = d
				break
			}
		}
		high := -1
		for d := 9; d >= 0; d-- {
			if s.nonzero[t.letter] && d == 0 {
				continue
			}
			if !s.used[d] {
				high = d
				break
			}
		}
		if low < 0 || high < 0 {
			return 0, 0, false
		}
		min += t.count * low
		max += t.count * high
	}
	return min, max, true
}

func hasCongruent(lo, hi, rem int) bool {
	if hi < lo {
		return false
	}
	delta := ((rem-lo)%10 + 10) % 10
	return lo+delta <= hi
}

func (s *solver) finishColumn(col int, c column, total int) bool {
	need := total % 10
	if d := s.digitOf[c.result]; d >= 0 {
		if d != need {
			return false
		}
		return s.solveColumn(col+1, total/10)
	}
	if (s.nonzero[c.result] && need == 0) || s.used[need] {
		return false
	}
	s.used[need] = true
	s.digitOf[c.result] = need
	if s.solveColumn(col+1, total/10) {
		return true
	}
	s.digitOf[c.result] = -1
	s.used[need] = false
	return false
}
